INSERT INTO chapter_doctrine_records VALUES (0, 25, 'literals', 'chapter 四百二十八', 1084, 1087, 1087, 'chapter-428-v1-unified-event-log-payload-kinds', 'RADICAL EVOLUTION SWEEP chapter 四百二十八 v1 closes at M1087 — UNIFIED EVENT LOG PAYLOAD-KINDS BACKBONE milestone。 Closes the audit-channel-fragmentation gap surfaced by the M1080 architecture audit。 4 cuts ship (M1084-M1087):(1) BASEventPayloadKind typed discriminator + accessors,(2) BASTurnLifecycleEventPayload + BASParallelStageEventPayload + factories,(3) BASPermitEscalationEventPayload + .from(ledger:) factory (additive — legacy ledger preserved),(4) BASEventLogProjectors + 4 named projector pure functions + chapter close-out。 ADR-014 OPT-IN held — purely additive payloads + projectors;no V1 hot path consumes them yet。 Original plan called for ledger deletions (~1,210 LOC) but those are deferred to a follow-up chapter under explicit user control。 V1 byte-equality preserved (5,700+ BAS tests pass)。');
