INSERT INTO chapter_doctrine_records VALUES (0, 28, 'literals', 'chapter 四百三十一', 1096, 1099, 1099, 'chapter-431-v1-native-apple-silicon-foundation', 'RADICAL EVOLUTION SWEEP chapter 四百三十一 v1 closes at M1099 — NATIVE APPLE SILICON FOUNDATION milestone。 Ships the FIRST substrate module to touch Metal / MPS / MPSGraph / Accelerate / CoreML at link-time + ship typed tensor primitives + ANE introspection + unified kernel registry。 4 cuts ship (M1096-M1099):(1) BASTensor + shape + descriptor,(2) BASANECapability + neural op vocabulary + probe actor,(3) BASMetalKernelRegistry actor + kernel contract,(4) 3 reference CPU kernels (matMul / rmsNorm / rotaryEmbedding) + chapter close-out。 ADR-014 OPT-IN held — no V1 hot path consumes BASMetalSubstrate yet;Phase F scheduler will be the first consumer。 V1 byte-equality preserved (5,700+ BAS tests pass)。');
INSERT INTO chapter_doctrine_knives VALUES (0, 28, 0, 1096, '第一刀', 'BASMetalSubstrate module entry — BASTensor typed property wrapper (phantom-rank + scalar evidence + discriminated MLX/CoreML/Metal/CPU backing) + BASTensorShape phantom-type ranks + BASTensorDescriptor Sendable wire envelope + Package.swift links 5 frameworks');
