INSERT INTO chapter_doctrine_records VALUES (0, 29, 'literals', 'chapter 四百三十二', 1100, 1103, 1103, 'chapter-432-v1-hardware-aware-scheduler-composition', 'RADICAL EVOLUTION SWEEP chapter 四百三十二 v1 closes at M1103 — HARDWARE-AWARE SCHEDULER COMPOSITION milestone。 Closes the consumption gap between Phase E BASMetalSubstrate primitives and the V2 runtime engine。 4 cuts ship (M1100-M1103):(1) BASTurnRuntimeEngineConfiguration 3-slot extension (runtimeMode + registry + capability),(2) BASTurnRuntimePlanDispatchProbe + engine wiring + per-call probe capture,(3) BASHardwareAwareScheduler actor + typed hint/assignment envelopes (first consumer of M1097 capability + M1098 registry),(4) chapter 四百三十二 v1 close-out + Phase 2 doctrine bump + ADR-016 bump。 ADR-014 OPT-IN preserved — no V1 hot path consumes the scheduler yet;default config keeps engine in v1ByteEqual mode with nil registry + nil capability。 V1 byte-equality preserved (5,700+ BAS tests pass)。 No default-mode flip — that needs CI dual-mode evidence first。');
INSERT INTO chapter_doctrine_knives VALUES (0, 29, 0, 1100, '第一刀', 'BASTurnRuntimeEngineConfiguration extension — 3 new optional slots (runtimeMode + metalKernelRegistry + aneCapability) + 3 with(...) updaters。 BASHostKit gains BASMetalSubstrate dependency。 Default config preserves V1 byte-equality (ADR-014 OPT-IN)');
INSERT INTO chapter_doctrine_knives VALUES (0, 29, 1, 1101, '第二刀', 'BASTurnRuntimePlanDispatchProbe Sendable + Codable typed snapshot + BASTurnRuntimeEngine wires 3 config slots into actor storage + adds lastPlanDispatchProbe/currentDispatchProbe accessors + runWithPlan captures the probe per call (proving the wiring fires)');
INSERT INTO chapter_doctrine_knives VALUES (0, 29, 2, 1102, '第三刀', 'BASHardwareAwareScheduler actor (~270 LOC) + BASStageAcceleratorHint (6-field) + BASStageAcceleratorAssignment (5-field) + 3 rationale enums。 Cost function: (latency × thermalDerate) + (energy × powerWeight) + opSupportPenalty。 First consumer of M1097 capability + M1098 registry');
INSERT INTO chapter_doctrine_knives VALUES (0, 29, 3, 1103, '第四刀', 'chapter 四百三十二 v1 close-out doctrine + Phase 2 doctrine bump (chapter count 26 → 27, mNumberLast 1099 → 1103, commitsShipped 133 → 137) + ADR-016.M1099 → ADR-016.M1103 bump。 No default-mode flip — needs CI dual-mode verification first');
