INSERT INTO chapter_doctrine_records VALUES (0, 33, 'literals', 'chapter 四百三十六', 1120, 1123, 1123, 'chapter-436-v1-first-ledger-driven-dispatch', 'POST-RADICAL EVOLUTION SWEEP chapter 四百三十六 ships FIRST LEDGER-DRIVEN DISPATCH across 4 cuts (M1120-M1123)。 Closes the gap between chapter 435''s scheduler-consumption (decisions captured) and actual ledger-driven dispatch (decisions honored)。 4 cuts:(1) BASNativeStageDispatchLedger typed evidence surface,(2) executePlanWithAssignments(...) + RoutedStageExecutor closure,(3) 11 tests proving end-to-end ledger consumption,(4) chapter close-out + bumps。 ADR-014 OPT-IN preserved — empty assignments → fallback path → V1 byte-equal。 V1 byte-equality preserved (5,770+ BAS tests pass)。 First chapter where ''scheduler decided X → executor honored X'' is a verifiable end-to-end invariant。');
INSERT INTO chapter_doctrine_knives VALUES (0, 33, 0, 1120, '第一刀', 'BASNativeStageDispatchLedger typed evidence: BASNativeStageExecutionRecord (5 fields) + BASNativeStageDispatchLedger (records + 4 typed aggregates) +.empty sentinel + immutable appending(_:) updater');
INSERT INTO chapter_doctrine_knives VALUES (0, 33, 1, 1121, '第二刀', 'BASNativeStageExecutor extension: RoutedStageExecutor typealias + executePlanWithAssignments(...) returns (stageLedger,dispatchLedger) tuple。 O(1) per-stage assignment lookup via indexed-by-rawvalue dictionary');
INSERT INTO chapter_doctrine_knives VALUES (0, 33, 2, 1122, '第三刀', 'Tests:11 new tests covering empty plan + no-assignment fall-through + full-assignment all-honored + mixed partial-honor + sequence index ordering + Codable round-trip');
