INSERT INTO chapter_doctrine_records VALUES (0, 34, 'literals', 'chapter 四百三十七', 1124, 1127, 1127, 'chapter-437-v1-end-to-end-routed-dispatch', 'POST-RADICAL EVOLUTION SWEEP chapter 四百三十七 ships END-TO-END ROUTED DISPATCH across 4 cuts (M1124-M1127)。 Closes the FINAL gap between chapter 435''s scheduler-consumption (decisions captured) + chapter 436''s ledger-driven dispatch (decisions honored at executor layer)。 Now a single runWithPlan(...) call provably:(1) captures assignment ledger,(2) routes through delegate→executor when ledger non-empty,(3) honors per-stage assignments,(4) captures dispatch ledger。 4 cuts:(1) recon,(2) delegate.runScaffoldedWithAssignments(...) bridge,(3) engine wiring (lastDispatchLedger field + accessor + runWithPlan branch),(4) chapter close-out + bumps。 ADR-014 OPT-IN preserved — empty ledger → unrouted path = pre-M1124 behavior。 V1 byte-equality preserved (5,790+ BAS tests pass)。 First chapter where a single runWithPlan(...) call produces TWO typed ledgers (assignments + dispatch) proving end-to-end:scheduler decided X → executor honored X for stage Y。');
INSERT INTO chapter_doctrine_knives VALUES (0, 34, 0, 1124, '第一刀', 'Recon BASRuntimeInternalDelegate + BASNativeStageExecutor topology;design routedExecutor passing path through delegate boundary (no source change)');
INSERT INTO chapter_doctrine_knives VALUES (0, 34, 1, 1125, '第二刀', 'BASRuntimeInternalDelegate.runScaffoldedWithAssignments(request:assignments:routedExecutor:fallbackExecutor:) — bridges M1121 executor''s routed path through the delegate boundary。 Both closure params default to no-op for back-compat。 Returns (stageLedger,dispatchLedger) tuple');
INSERT INTO chapter_doctrine_knives VALUES (0, 34, 2, 1126, '第三刀', 'BASTurnRuntimeEngine wiring:NEW lastDispatchLedger actor field + lastNativeStageDispatchLedger() accessor + runWithPlan(...) branches on lastAssignmentLedger.recordCount > 0 (routed) vs == 0 (unrouted = V1 byte-equal)');
