INSERT INTO chapter_doctrine_records VALUES (0, 35, 'literals', 'chapter 四百三十八', 1128, 1131, 1131, 'chapter-438-v1-host-side-injection', 'POST-RADICAL EVOLUTION SWEEP chapter 四百三十八 ships HOST-SIDE INJECTION across 4 cuts (M1128-M1131)。 Closes the substrate-side gap that prevented hosts from injecting real backend dispatch closures into the chapter 437 end-to-end routed dispatch path。 4 cuts:(1) BASTurnRuntimeEngineConfiguration 2 new optional slots,(2) BASTurnRuntimeEngine wiring,(3) 7 host-injection tests,(4) chapter close-out + bumps。 ADR-014 OPT-IN preserved — empty closures → engine uses no-op defaults = pre-M1128 behavior identical。 V1 byte-equality preserved (5,800+ BAS tests pass)。 First chapter where Qinao SDK can plug mlxArray → BASMLXAdapter dispatch into substrate end-to-end via a single config slot。 Substrate-side end-to-end is now COMPLETE; remaining "更硬核" gap is purely host-side (write the closure bodies that bind to specific backends)。');
INSERT INTO chapter_doctrine_knives VALUES (0, 35, 0, 1128, '第一刀', 'BASTurnRuntimeEngineConfiguration 2 new optional slots:routedStageExecutor + fallbackStageExecutor。 2 new with(...) updaters。 All 7 existing updaters thread the 2 new fields through (replace_all batch edit)。 Init back-compat preserved');
