INSERT INTO chapter_doctrine_records VALUES (0, 38, 'literals', 'chapter 四百四十一', 1140, 1143, 1143, 'chapter-441-v1-plan-assignment-event-type', 'POST-RADICAL EVOLUTION SWEEP chapter 四百四十一 ships PLAN-ASSIGNMENT EVENT TYPE across 4 cuts (M1140-M1143)。 Closes the upstream half of the routed-dispatch replay surface (the downstream dispatch HONOR half landed in chapter 440):scheduler decisions CAPTURED at probe time now flow through the unified event log automatically。 4 cuts:(1) typed payload + factory + projector + 6th BASEventPayloadKind case,(2) engine wiring with 2 guards + try? error swallowing,(3) 16 pin tests,(4) chapter close-out + bumps。 ADR-014 OPT-IN preserved — gates skip emission when conditions don''t hold。 V1 byte-equality preserved。 First chapter where the substrate''s replay surface is COMPLETE — 6 typed payload kinds carry the FULL routed-dispatch story (capture → honor) through ONE canonical event log。');
INSERT INTO chapter_doctrine_knives VALUES (0, 38, 0, 1140, '第一刀', 'BASTurnRuntimePlanAssignmentEventPayload typed Codable payload + 7-field record mirror + .from(ledger:) factory + BASEventLogEntry.planAssignmentEvent(...) factory + reverse accessor + projector + new BASEventPayloadKind.planAssignment case (rawvalue "plan-assignment-event")');
INSERT INTO chapter_doctrine_knives VALUES (0, 38, 1, 1141, '第二刀', 'BASTurnRuntimeEngine wiring: lastEmittedPlanAssignmentEventID actor field + lastEmittedPlanAssignmentEventIDValue() accessor + emitPlanAssignmentEventIfNeeded(...) helper。 runWithPlan(...) calls helper AFTER dispatch auto-emit so plan-assignment event lands chronologically after dispatch event (capture → honor temporal order preserved)');
INSERT INTO chapter_doctrine_knives VALUES (0, 38, 2, 1142, '第三刀', 'Tests:12 payload pin tests + 4 engine accessor pin tests = 16 new tests。 Covers factory empty + populated + Codable round-trip + factory stamps + reverse accessor + projector filter+sort + foreign-kind filter + raw-value stability + 6-cases count + determinism + accessor signature + guard skip empty + guard emit populated + storage append compile pin');
