INSERT INTO chapter_doctrine_records VALUES (0, 40, 'literals', 'chapter 四百四十三', 1148, 1151, 1151, 'chapter-443-v1-cross-session-replay-assembly', 'POST-RADICAL EVOLUTION SWEEP chapter 四百四十三 ships CROSS-SESSION REPLAY ASSEMBLY across 4 cuts (M1148-M1151)。 Closes the last gap on the substrate-side replay surface for distributed consumers (G8 SSM training, causal graph extraction,distributed audit): typed bundle composition + async cross-session factory pulling from BASEventLogStorage directly。 4 cuts:(1) recon storage cross-session API + merge semantics design,(2) BASEventLogReplayBundle.merging(_:) + .combining(_:) + BASEventLogProjectors.projectAcrossAllSessions(from:) async factory, (3) 14 cross-session integration tests,(4) chapter close-out + bumps。 ADR-014 OPT-IN preserved — purely additive。 V1 byte-equality preserved。 First chapter where the substrate''s 6-kind replay surface offers a complete typed API for distributed consumers — pulling events across all sessions directly from storage + composing bundles deterministically without boilerplate。');
INSERT INTO chapter_doctrine_knives VALUES (0, 40, 0, 1148, '第一刀', 'Recon BASEventLogStorage.events(sinceTimestampMs:limit:) confirmed as the cross-session globally-time-ordered accessor。 Designed merge semantics: per-kind concatenation in input order; cross-session events kept in global time-order via storage protocol''s (timestampMs ASC, sequenceNumber ASC) invariant。 No source change');
INSERT INTO chapter_doctrine_knives VALUES (0, 40, 1, 1149, '第二刀', 'BASEventLogReplayBundle.merging(_:) instance method + .combining(_:) static factory + BASEventLogProjectors.projectAcrossAllSessions(from:sinceTimestampMs:limit:) async factory pulling events directly from BASEventLogStorage and returning the 6-kind bundle。 Defaults since: 0 (all-time) and limit: Int.max (everything)');
INSERT INTO chapter_doctrine_knives VALUES (0, 40, 2, 1150, '第三刀', '14 cross-session integration tests in BASEventLogCrossSessionReplayTests: 3 merging(_:) + 3 combining(_:) + 6 projectAcrossAllSessions + 2 determinism。 Proves merge is byte-deterministic in input order + storage cross-session accessor honored by the async factory');
