INSERT INTO chapter_doctrine_records VALUES (0, 41, 'literals', 'chapter 四百四十四', 1152, 1155, 1155, 'chapter-444-v1-per-stage-event-payload', 'POST-RADICAL EVOLUTION SWEEP chapter 四百四十四 ships PER-STAGE EVENT PAYLOAD across 4 cuts (M1152-M1155)。 Closes chapter 442 future-cut #3:per-stage event payload (one entry per stage step,not per turn) for fine-grained causal-graph extraction at the stage level without unbundling the per-turn aggregate。 4 cuts:(1) recon shape + design,(2) BASNativeStagePerStepEventPayload typed Codable + factory + projector + 7th BASEventPayloadKind case + EXTENDED BASEventLogReplayBundle to 7 fields,(3) 13 pin tests,(4) chapter close-out + bumps。 ADR-014 OPT-IN preserved — purely additive。 V1 byte-equality preserved。 Engine does NOT auto-emit per-step events (would 5-10x event log volume);hosts opt-in via direct emission。 Sibling,not replacement,of chapter 439 per-turn dispatch payload。');
