INSERT INTO chapter_doctrine_knives VALUES (0, 45, 1, 1169, '第二刀', 'BASMPSGraphRMSNormKernel actor — first MPSGraph usage in substrate:graph composes mul + reduceMean + add + sqrt + div + mul ops;graph.run(...) with pre-allocated MTLBuffer output → byte-equal Data return。 Typed epsilon param (default 1e-6)');
INSERT INTO chapter_doctrine_knives VALUES (0, 45, 2, 1170, '第三刀', '4 PROOF tests:construction-or-skip + single-batch known result + per-feature weight modulation + GPU/CPU agreement within 1e-4 tolerance (rmsNorm sqrt+divide more numerically sensitive than matMul,absolute tolerance documented as design choice)');
