INSERT INTO chapter_doctrine_knives VALUES (0, 46, 1, 1173, '第二刀', 'BASMPSGraphRotaryEmbeddingKernel actor — MPSGraph composes reshape(seq,halfDim,2) + slice even/odd + 4 muls + sub + add + reshape back + concat。 dispatches via graph.run(...) into pre-allocated MTLBuffer。 「原生利用神经引擎」 3/3 complete');
