INSERT INTO chapter_doctrine_records VALUES (0, 47, 'literals', 'chapter 四百五十', 1176, 1179, 1179, 'chapter-450-v1-first-biomimetic-ssm-primitive', 'POST-SWEEP BIOMIMETIC chapter 450 ships substrate''s FIRST stateful + selective-gated primitive。 4 cuts (M1176-M1179):design + BASMambaSSMState actor + 9 PROOF tests + close-out。 Hidden state h:(B,D,N) persists across selectiveScan() calls — canonical Mamba update dA=exp(Δ·A) + dB=Δ·B + h=dA·h+dB·x + y=sum_n(C·h)。 testStatePersistsAcrossCalls proves recurrence;testZeroDeltaFreezesState proves selective gating;testMultiBatchIndependence proves isolation;testMultiTimestepScanMatchesSequential proves algorithmic correctness。 「不够仿生」 0/10 → 4/10。 Chapter 451 (next) accelerates GPU;chapter 452 adds predictive-coding adaptation loop (addresses 「不够灵活」)。 ADR-016 → M1179。 V1 byte-equality preserved。');
INSERT INTO chapter_doctrine_knives VALUES (0, 47, 0, 1176, '第一刀', 'Design BASMambaSSMState typed primitive: typed shape + typed input/output bundles + canonical selective-scan algorithm specification。 No source change');
INSERT INTO chapter_doctrine_knives VALUES (0, 47, 1, 1177, '第二刀', 'BASMambaSSMState actor — substrate''s first stateful primitive。 Hidden state h:(B,D,N) persists across selectiveScan() calls。 CPU baseline implements canonical Mamba update:dA=exp(Δ·A) + dB=Δ·B + h=dA·h+dB·x + y=sum_n(C·h)。 Typed error + auxiliary audit accessors');
INSERT INTO chapter_doctrine_knives VALUES (0, 47, 2, 1178, '第三刀', '9 PROOF tests in BASMambaSSMStateTests: construction-zeroes + shape-clamp + reset + single-step canonical (h=3.0,y=12.0) + STATE PERSISTENCE across calls (the biomimetic proof) + Δ=0 FREEZES STATE (selective gating proof) + multi-batch independence + multi-step == sequential + shape mismatch typed throw');
INSERT INTO chapter_doctrine_knives VALUES (0, 47, 3, 1179, '第四刀', 'chapter 450 close-out + Phase 2 bump (commits 221 → 225,chapter count 47 → 48) + ADR-016.M1175 → M1179 advance + postSweepRealExecutionEntries entry。 「不够仿生」 0/10 → 4/10');
