INSERT INTO chapter_doctrine_records VALUES (0, 48, 'literals', 'chapter 四百五十一', 1180, 1183, 1183, 'chapter-451-v1-mamba-gpu-via-custom-metal-shader', 'POST-SWEEP BIOMIMETIC chapter 451 adds GPU acceleration to chapter 450''s BASMambaSSMState primitive。 4 cuts (M1180-M1183):design + selectiveScanGPU(...) method with runtime-compiled Metal compute shader + 3 PROOF tests + close-out。 Custom Metal kernel dispatches B×D threads,each running the sequential timestep loop for its (batch,hidden) pair。 GPU + CPU paths share the SAME actor-isolated hidden state — interleaved calls all see + mutate it correctly (proven by testMixedGPUCPUCallsShareState)。 First custom Metal shader in substrate (chapters 447-449 used MPS/MPSGraph)。 「不够仿生」 4/10 → 5/10。 ADR-016 → M1183。 V1 byte-equality preserved。');
INSERT INTO chapter_doctrine_knives VALUES (0, 48, 0, 1180, '第一刀', 'Recon BASMambaSSMState CPU baseline + designed Metal compute shader (parallel across batch × hiddenDim grid,sequential over timesteps per thread)。 No source change');
INSERT INTO chapter_doctrine_knives VALUES (0, 48, 1, 1181, '第二刀', 'Extended BASMambaSSMState with selectiveScanGPU(...) method + lazy Metal pipeline state + runtime-compiled shader via MTLDevice.makeLibrary(source:)。 NEW typed errors .gpuUnavailable + .gpuDispatchFailure。 GPU + CPU paths share the SAME hidden state — callers can interleave freely');
INSERT INTO chapter_doctrine_knives VALUES (0, 48, 2, 1182, '第三刀', '3 NEW GPU PROOF tests in BASMambaSSMStateTests:GPU-matches-CPU on realistic B=2, L=5,D=4,N=3 input + GPU state persistence + MIXED GPU/CPU interleaved calls share same state (proves shared mutable state, not parallel copies)。 Total Mamba tests: 9 → 12');
INSERT INTO chapter_doctrine_knives VALUES (0, 48, 3, 1183, '第四刀', 'chapter 451 close-out + Phase 2 bump (commits 225 → 229,chapter count 48 → 49) + ADR-016.M1179 → M1183 + postSweepRealExecutionEntries entry');
