INSERT INTO chapter_doctrine_records VALUES (0, 50, 'literals', 'chapter 四百五十三', 1188, 1191, 1191, 'chapter-453-v1-attention-quartet-complete', 'POST-SWEEP REAL EXECUTION chapter 453 adds attention to the substrate kernel triad (matMul + rmsNorm + rotaryEmbedding) → QUARTET。 4 cuts (M1188-M1191):design + CPU baseline + MPSGraph GPU sibling + 5 PROOF tests + close-out。 CPU softmax with row-wise max-shift numerical stability;GPU composes transpose + matMul + softMax + scale in one MPSGraph executable。 「原生利用神经引擎」 3/3 → 4/4 (substrate has every primitive a modern transformer attention block needs)。 ADR-016 → M1191。 V1 byte-equality preserved。');
INSERT INTO chapter_doctrine_knives VALUES (0, 50, 0, 1188, '第一刀', 'Design BASAttentionKernel CPU + GPU. Scaled dot-product attention:scores = Q·K^T/sqrt(D),attn = softmax(scores), output = attn·V。 Single-head;multihead = batched single-head');
INSERT INTO chapter_doctrine_knives VALUES (0, 50, 1, 1189, '第二刀', 'BASAttentionKernel (CPU,struct,struct Sendable) + BASMPSGraphAttentionKernel (GPU,actor)。 CPU softmax via row-wise max-shift for numerical stability。 GPU MPSGraph composition with transpose + matMul + softMax + scale。 First MPSGraph composition combining softMax + matMul on real tensors');
INSERT INTO chapter_doctrine_knives VALUES (0, 50, 2, 1190, '第三刀', '5 PROOF tests:CPU single-token identity (softmax=[1.0]) + uniform-K produces uniform attn + dominant-K concentrates + GPU construction probe + GPU matches CPU on 3×5 attention within 1e-4');
INSERT INTO chapter_doctrine_knives VALUES (0, 50, 3, 1191, '第四刀', 'chapter 453 close-out + Phase 2 bump (commits 233 → 237,chapter count 50 → 51) + ADR-016.M1187 → M1191 + postSweepRealExecutionEntries entry。 「原生利用神经引擎」 3/3 → 4/4 (transformer kernel quartet complete)');
