INSERT INTO chapter_doctrine_records VALUES (0, 51, 'literals', 'chapter 四百五十四', 1192, 1195, 1195, 'chapter-454-v1-first-substrate-learning-primitive', 'POST-SWEEP BIOMIMETIC chapter 454 ships substrate''s FIRST learning primitive。 4 cuts (M1192-M1195):design + BASPlasticityFold actor with 3 plasticity rules (hebbian + antiHebbian + outcomeModulatedHebbian) + 12 PROOF tests + close-out。 testHebbianLearnsAssociation proves the substrate learns from repeated (pre,post) pairs:after 10 updates forward([1,0,0])≈[0,1,0]。 outcome=0 freezes learning;sign of outcome reinforces or anti-reinforces (biology analogue:dopaminergic gating)。 Substrate now has BOTH adaptation (chapter 452) AND learning (chapter 454)。 「不够灵活」 ~35% → ~50%。 ADR-016 → M1195。 V1 byte-equality preserved。');
INSERT INTO chapter_doctrine_knives VALUES (0, 51, 0, 1192, '第一刀', 'Design BASPlasticityFold typed primitive: typed shape + 3-rule enum + typed update bundle + canonical Hebbian/anti-Hebbian/outcome-modulated specifications。 No source change');
INSERT INTO chapter_doctrine_knives VALUES (0, 51, 1, 1193, '第二刀', 'BASPlasticityFold actor — substrate''s FIRST learning primitive。 Maintains weight matrix W:(preDim × postDim) across apply() calls。 3 selectable rules under one actor (single source-of-truth)。 forward(pre:) read-only projection query。 Audit accessors + reset() + typed error + shape clamps');
INSERT INTO chapter_doctrine_knives VALUES (0, 51, 2, 1194, '第三刀', '12 PROOF tests including HEBBIAN LEARNS ASSOCIATION:10 repeats of pre=[1,0,0] post=[0,1,0] → forward([1,0,0])≈[0,1,0] (bedrock plasticity proof);outcome=0 freezes outcome-modulated rule;outcome sign reinforces/anti-reinforces');
INSERT INTO chapter_doctrine_knives VALUES (0, 51, 3, 1195, '第四刀', 'chapter 454 close-out + Phase 2 bump (commits 237 → 241,chapter count 51 → 52) + ADR-016.M1191 → M1195 advance + postSweepRealExecutionEntries entry。 「不够灵活」 ~35% → ~50%');
