INSERT INTO chapter_doctrine_records VALUES (0, 54, 'literals', 'chapter 四百五十七', 1204, 1207, 1207, 'chapter-457-v1-stdp-timing-window-plasticity', 'POST-SWEEP BIOMIMETIC chapter 457 ships the 4th plasticity rule — canonical Spike-Timing-Dependent Plasticity (Bi & Poo 1998 + Markram et al 1997)。 4 cuts (M1204-M1207):design + STDP rule implementation + 16 PROOF tests (LTP / LTD / zero-Δt / exponential decay / asymmetric A and τ / observer-routing / Codable backward-compat) + close-out。 The Bi & Poo defaults (A_+ = A_- = 1.0,τ_+ = τ_- = 20 ms) + chapter 一百八十五 boundary clamps (amplitudes >= 0,τ >= 1e-6) keep the typed surface safe。 Substrate now learns CAUSAL ORDERING via spike-timing windows,not just correlations。 4th rule plugs into the same BASPlasticityFold actor + same observer signal bundle + same snapshot persistence — fully compositional with chapters 454/455/456。 「不够仿生」 6/10 → 7/10。 ADR-016 → M1207。 V1 byte-equality preserved。');
INSERT INTO chapter_doctrine_knives VALUES (0, 54, 0, 1204, '第一刀', 'Design BASPlasticitySTDPParams (typed (A_+,A_-,τ_+,τ_-) bundle with chapter 一百八十五 clamps,canonical Bi & Poo defaults) + .stdpTemporal 4th rule case + extended apply(... timingDelta:) + extended BASBiomimeticTurnSignal plasticityTimingDelta field');
INSERT INTO chapter_doctrine_knives VALUES (0, 54, 1, 1205, '第二刀', 'Ship STDP rule in BASPlasticityFold.apply switch:amplitude = +A_+·exp(-Δt/τ_+) for LTP,-A_-·exp(Δt/τ_-) for LTD,0 at Δt=0。 BASPlasticityFoldShape Codable backward-compat (pre-457 JSON defaults stdpParams to canonical values)。 BASPlasticityUpdate gains timingDelta + stdpAmplitude fields。 BASBiomimeticTurnObserver routes timingDelta through');
INSERT INTO chapter_doctrine_knives VALUES (0, 54, 2, 1206, '第三刀', '16 PROOF tests covering LTP (Δt>0) / LTD (Δt<0) / zero-Δt / exponential decay / asymmetric A_+/A_- (4× bias) / asymmetric τ_+/τ_- (20× window ratio) / non-STDP-rules-ignore-timingDelta / observer-routing / signal-default-timingDelta-0 / shape Codable round-trip + BACKWARD-COMPAT (legacy JSON missing stdpParams defaults to canonical Bi & Poo) / snapshot preserves STDP shape');
