INSERT INTO chapter_doctrine_records VALUES (0, 56, 'literals', 'chapter 四百五十九', 1212, 1215, 1215, 'chapter-459-v1-hierarchical-predictive-coding', 'POST-SWEEP BIOMIMETIC chapter 459 ships substrate''s FIRST multi-level adaptive primitive — BASHierarchicalPredictiveCoding。 4 cuts (M1212-M1215):design + N-layer hierarchy actor + 12 PROOF tests + close-out。 Cascade propagation:layer K sees layer K-1''s prediction error,not the raw input;only irreducible surprise reaches the top layer。 Equal-dim invariant keeps the cascade simple — no inter-layer projection needed。 Custom Codable init ENFORCES the invariant on DECODE (malformed JSON fails loudly)。 Aggregate snapshot via chapter 455 integration covers entire stack in one Codable value。 Top-layer error = system''s abstract anomaly signal at any moment。 Substrate now mirrors cortical hierarchies (Rao & Ballard 1999; Friston free-energy principle)。 「不够仿生」 7/10 → 8/10。 ADR-016 → M1215。 V1 byte-equality preserved。');
INSERT INTO chapter_doctrine_knives VALUES (0, 56, 0, 1212, '第一刀', 'Design BASHierarchicalPredictiveCoding typed shape (array of probe shapes, equal-dim invariant) + observation bundle (perLayer results + topLayerError + topLayerMSE) + snapshot aggregate + typed error。 Equal-dim invariant keeps cascade simple — no inter-layer projection needed;hosts wanting differential dims wire their own projections。 No source change');
INSERT INTO chapter_doctrine_knives VALUES (0, 56, 1, 1213, '第二刀', 'Ship BASHierarchicalPredictiveCoding actor:holds N probes;observe(_:) cascades error up the stack (layer K sees layer K-1''s error);exportSnapshot/importSnapshot integrate chapter 455 per-probe snapshots into one aggregate;reset cascades。 Custom Codable init on shape ENFORCES equal-dim invariant on DECODE (chapter 一百八十五 boundary-clamp on malformed JSON)');
INSERT INTO chapter_doctrine_knives VALUES (0, 56, 2, 1214, '第三刀', '12 PROOF tests covering empty-layers / dim-mismatch / single-layer-matches-standalone / cascade-propagates-error / cascade-with-learning-zeroes-error / top-layer-MSE-converges / input-dim-mismatch / snapshot-round-trip-preserves-all-layers (subsequent observe byte-equal across fresh + restored hierarchy) / reset-cascades / import-shape-mismatch / Codable-decode-enforces-equal-dim-invariant on malformed JSON');
