INSERT INTO chapter_doctrine_records VALUES (0, 57, 'literals', 'chapter 四百六十', 1216, 1219, 1219, 'chapter-460-v1-benchmark-debt-closed', 'DEBT REPAYMENT chapter 1 closes the benchmark debt surfaced by chapter 459 self-audit。 4 cuts (M1216-M1219):typed shape + report + harness actor + 7 PROOF tests including real harness run on 3 production shapes。 Real measurements caught a NUANCE the fictional doctrine numbers hid:GPU is SLOWER than CPU at tiny shapes (32×32 → 0.66x speedup) due to kernel-launch + buffer-alloc overhead; GPU dominates at production-relevant shapes (256×256 → 33.9x;1024×1024 → 138.0x)。 Chapter 458 doctrine UPDATED to remove fictional µs numbers and cite the harness + real dev-machine measurements with hardware-varies caveat。 Same epistemological failure mode as chapter 446 SWEEP — caught + fixed。 ADR-016 → M1219。 V1 byte-equality preserved。');
INSERT INTO chapter_doctrine_knives VALUES (0, 57, 0, 1216, '第一刀', 'Design BASMetalBenchmarkShape (preDim × postDim × warmupIterations × timedIterations,chapter 一百八十五 clamps) + BASMetalBenchmarkReport (CPU + GPU sample arrays + gpuAvailable flag + derived mean/median/p95/speedup + summary string for doctrine copy-paste)。 No source change');
INSERT INTO chapter_doctrine_knives VALUES (0, 57, 1, 1217, '第二刀', 'Ship BASMetalBenchmarkHarness actor in Sources/BASMetalSubstrate/。 runPlasticity(shape:) runs warmup + timed iterations on BOTH CPU + GPU paths,catches gpuUnavailable gracefully (sets gpuAvailable=false),returns typed report');
INSERT INTO chapter_doctrine_knives VALUES (0, 57, 2, 1218, '第三刀', '7 PROOF tests including REAL HARNESS RUN on 3 production shapes (32×32 / 256×256 / 1024×1024) emitting measured µs to test logs。 Assertions are STRUCTURE-only (positive,non-NaN,monotonic percentiles) — specific µs numbers are NEVER asserted (hardware varies)。 Real measurements: 32×32→0.66x (GPU SLOWER,dispatch overhead);256×256→33.9x;1024×1024→138.0x');
